// Combines supabase/migrations/*.sql into one file that can be pasted into the
// Supabase SQL Editor (for setting up a hosted project without the CLI).
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = "supabase/migrations";
const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();
const parts = [
  "-- 661C Home Hub — database setup (GENERATED by `npm run db:bundle`; do not edit).",
  "-- Paste ALL of this into Supabase → SQL Editor → New query → Run. Run it once, on a new project.",
  ...files.map((f) => `\n-- ===== ${f} =====\n${readFileSync(join(dir, f), "utf8")}`),
];
writeFileSync("supabase/setup-all-in-one.sql", parts.join("\n"));
console.log(`Wrote supabase/setup-all-in-one.sql from ${files.length} migrations`);
